local patches={{Path="ReplicatedStorage/RarePullCard",Patches={{23313,0,table.concat({""})},{23582,0,table.concat({"O2xvY2FsIGZyb209UnVsZXMuQ29sbGVjdEZyb20odGwp"})},{23648,5,table.concat({"ZnJvbQ=="})}}},{Path="ReplicatedStorage/RarePullCinematic",Patches={{6083,0,table.concat({""})},{18333,0,table.concat({"LGhvbGROb3c="})},{18585,19,table.concat({"Q29sbGVjdEZyb20gKFIxNThtOiB0aGUgcmVzdWx0J3Mgd2hvbGUgYW5pbWF0aW9uIGhhcyBwbGF5ZWQ7IGl0IHdhczogYWZ0ZXIgdGhlIHJlc3VsdCBpcyBzaG93bik="})},{19388,0,table.concat({""})},{25875,0,table.concat({"O2IuQ29sbGVjdEZyb209Y29sbGVjdEZyb20ocnVuKQ=="})},{26229,0,table.concat({"O2IuQ29sbGVjdEZyb209Y29sbGVjdEZyb20ocnVuKSAtLSAoUjE1OG06IHRoZSByZWFsIHZhbHVlOiB0aGUgY2FyZCdzIGhpbnQgY291bnRzIGZyb20gaXQp"})},{29288,0,table.concat({""})},{29812,20,table.concat({"YW5kIHJ1bi5DbG9jaygpPj1jb2xsZWN0RnJvbShydW4pdGhlbiByZXR1cm4nbWVudSdlbmQgLS0gKFIxNThtOiBiZWZvcmUgdGhlIGFuaW1hdGlvbiBoYXMgcGxheWVkIHRoZSBtZW51IGlzIGlnbm9yZWQ6IGl0IHBsYXlzIG9uKQ=="})},{33177,0,table.concat({"IHJ1bi5Db2xsZWN0RnJvbT1SdWxlcy5Db2xsZWN0RnJvbShydW4uVEwpIC0tIChSMTU4bTogdGhlIHJlYWwgdGltZWxpbmUnczogd2hlbiB0aGUgd2hvbGUgcmVzdWx0IGFuaW1hdGlvbiBoYXMgcGxheWVkKQo="})},{38181,0,table.concat({""})},{44297,0,table.concat({"aG9sZE5vdz1mdW5jdGlvbihydW4paWYgbm90IHJ1bi5Eb25lIGFuZCBydW4uSGVsZCB0aGVuIHBhcnQocnVuLCd0b29sJyxob2xkVG9vbCxydW4sYXJtZWQocnVuLDApb3IgcnVuLktpbmQ9PSdTY2VuZScpZW5kIGVuZAo="})},{51425,0,table.concat({"LS0gUjE1OG06IGFmdGVyIHRoZSBoaXQgaXRzIHByZXNzIGlzIGEgY29sbGVjdCBsaWtlIGFueSBvdGhlcjogaXQgb25seSBsYW5kcyBmcm9tIENvbGxlY3RGcm9tICsgQ29sbGVjdEFmdGVyICh0aGUgYW5pbWF0aW9uIGFsd2F5cyBwbGF5cyBvdXQpLgo="})},{51670,7,table.concat({"Y29sbGVjdEZyb20ocnVuKQ=="})},{51714,0,table.concat({"IC0tIChSMTU4bTogbm90IGJlZm9yZSB0aGUgd2hvbGUgcmVzdWx0IGFuaW1hdGlvbiBoYXMgcGxheWVkLCBub3IgaW4gdGhlIGZpcnN0IENvbGxlY3RBZnRlciBzIG9mIGl0KQ=="})},{54400,0,table.concat({"IC0tIChSMTU4bTogYW5kIGFmdGVyIGl0cyB3aG9sZSBhbmltYXRpb24gaGFkIHBsYXllZDogQ29sbGVjdEZyb20gKyBDb2xsZWN0QWZ0ZXIpCg=="})},{54674,0,table.concat({"LS0gUjE1OG0